import {STM32_BOARDS} from './stm32-boards.js';
// This is model coverage, not a claim that every MCU implements each peripheral.
export const STM_SCOPE=[
 ['CPU / exception / FPU','Kısmi','Gerçek Cortex-M3/M4F komut motoru, NVIC, SysTick, WFI/WFE/SEV ve M4F aritmetiği.','MPU, cache, cycle-accurate pipeline/bus, tüm fault/priority ayrıntıları.'],
 ['Flash / SRAM / reset','Kısmi','Kartın kendi bellek sınırı, reset vektörü, data/bss ve firmware hedef kontrolü.','Flash programlama/erase, option bytes, ROM bootloader ve fiziksel NRST/BOOT devresi.'],
 ['RCC / saat / güç','Kısmi','Kart HSE/PLL/APB başlangıcı, çevrebirim enable/reset; RTC clock kaynakları ve PWR DBP/VOS/ready, F4 PLL öncesi doğru VOS seçimi.','Dinamik tüm saat ağacı, clock failure/CSS, PVD/BOR, STOP/STANDBY ve güç tüketimi.'],
 ['GPIO / EXTI / debug','Kısmi','GPIO/pull/open-drain, gerçek DC hatları; EXTI0..15 port mux, edge, mask, PR W1C, SWIER, IRQ ve WFE event.','Dahili EXTI hatları, tüm AF/remap tablosu, I/O slew/damage; SWD/JTAG/ITM/trace donanımı.'],
 ['USART1 / USART2','Kısmi','USART1/2 DMA istekleri; USART1 ve uygun Blue Pill/WeAct USART2 fiziksel 7E/O,8N/E/O,9N,1/2stop / PE-RXNE-TXE-TC-ORE-FE / IRQ; kart terminali.','OVER8,0.5/1.5stop,CTS/RTS/LIN/smartcard/synchronous; Nucleo fiziksel VCP ve USART2 alternatif başlık/remap.'],
 ['ADC1 / diğer ADC / DAC','Kısmi','ADC1 regular/continuous, 12/10/8/6bit, EOC/OVR/IRQ; injected/offset/JAUTO, regular/injected discontinuous, analog watchdog, EXTI11/TIM2 regular ve EXTI15/TIM2_CC1 injected trigger ve gerçek DMA SRAM.','Dahili kanallar, diğer injected dış tetikler, sample-hold/noise/kalibrasyon, diğer ADC/DAC.'],
 ['TIM2 / diğer timer','Kısmi','PWM1/2 ve output compare, match/update IRQ, UDIS/URS/one-pulse; direct/indirect input capture; encoder TI1/TI2/PSC/DIR ve fiziksel netler; CEN/RCC/CNT/UG prescaler fazı; DIR aşağı sayım, CMS1/2/3 merkez hizalı PWM ve compare/update IRQ.','Digital filter/TRC/remap/external clock/dead-time, encoder trigger/index ve dynamic APB saat alt fazı, diğer TIM/LPTIM/HRTIM.'],
 ['SPI1 / SPI2+ / I²S / SAI','Kısmi','SPI1 mode0..3,8/16-bit,MSB/LSB master, software NSS/GPIO CS, gerçek hat/IRQ/OVR ve DMA RX/TX.','Hardware NSS/slave/CRC/remap/receive-only, SPI2+, I²S/SAI.'],
 ['I²C1 / I²C2+','Kısmi','Standard 7-bit master, ACK/POS/BTF/STOP, birleşik repeated-start okuma, EEPROM/ACK polling, fiziksel OD/clock wait/IRQ/recovery.','Fast/slave/multi-master/arbitration, DMA/PEC/SMBus, analog rise-time, I²C2+.'],
 ['DMA / bus arbitration','Kısmi','F1 DMA1 kanal/F4 DMA1+2 stream, native ARM bus read/write, normal/circular, width/increment/priority, HT/TC/TE IRQ; ADC1/SPI1/USART1+2 requests.','FIFO/burst/double-buffer/PFLOW, I²C DMA, bus contention ve diğer çevrebirim istekleri.'],
 ['RTC / backup / watchdog','Kısmi','F103 counter/F4 BCD calendar RTC, alarm/wakeup/IRQ, shadow/INIT/WPR, LSE/LSI/HSE, DBP/VOS, resetten korunan backup; IWDG/WWDG gerçek reset/RCC nedeni.','RTC tamper/timestamp/calibration/shift/subsecond/AF output, backup regulator; tolerans/debug/STOP/STANDBY ayrıntıları.'],
 ['CRC / RNG / crypto','Kısmi','32-bit CRC word register, 0x04c11db7 polinom, IDR/reset ve RCC kapısı; bağımsız CRC referansı ile dokuz kartta kabul.','RNG/crypto için MCU varlığı ve aileye özgü modeller; byte/halfword CRC feed desteklenmez.'],
 ['USB / CAN / Ethernet / SDIO','Kısmi','F103 PMA + F401/F411 OTG FS FIFO / IRQ67 / EP0 / bulk echo / sanal host ve F103 bxCAN loopback / mailbox / filtre / FIFO / IRQ. USB/CAN eşzamanlı kullanımı engellenir.','OTG host/isochronous/DMA ve sınıf sürücüleri; gerçek PC USB, sınıf sürücüleri, harici çok düğümlü CAN/transceiver; Ethernet/SDIO MCU varlığı ve modelleri.'],
 ['FMC / QSPI / DCMI / LCD / touch','Bekliyor','Opsiyonel Black Pill SPI flash footprint boş gösterilir.','Haricî bellek, kamera, ekran/touch çevrebirimleri; varlığı paket/MCUya bağlı.'],
 ['Dahili analog / sensörler','Bekliyor','Haricî devre sensörleri ve DC çözümü ayrı modellerdir.','Dahili sıcaklık/VREF, comparator/opamp, analog güç/kalibrasyon ayrıntıları.'],
 ['C17 / C++ / MicroPython','Kısmi','Gerçek Clang C17/C++17, çok dosya/linker/board bounds; constructor/init-array, SRAM heap/new/delete ve C IRQ bağlantısı; MicroPython WASM Pin/ADC/SoftI2C/SoftSPI devre modu.','Tam STL, exceptions/RTTI, thread/IRQ heap reentrancy, yerel ARM MicroPython portu ve tam Cube/vendor HAL.'],
 ['Kart / şema / doğrulama','Kısmi','Blue Pill, Nucleo ve WeAct kendi header/bellek/LED/KEY profilleri; örnek devre ve net label.','Tüm STM32 aileleri/kart revizyonları, M0/M7/M33, fiziksel cihaz karşılaştırması.'],
];
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function showSTMScope(board,showDialog){const b=STM32_BOARDS[board];showDialog('STM32 · Kapsam ve kontrol kaydı',`<p><strong>${esc(b.name)}</strong> · ${b.hz/1e6} MHz · ${b.flashSize/1024} KiB Flash / ${b.ram/1024} KiB SRAM</p><p>Bu tablo simülasyon kapsamını gösterir. Bir özelliğin kart çiziminde veya datasheetinde görünmesi, çalıştığı anlamına gelmez. Her MCU tüm çevrebirimleri içermez; çip ve paket varlığı datasheetten doğrulanır.</p><div style="overflow:auto"><table style="border-collapse:collapse;width:100%;table-layout:fixed;overflow-wrap:anywhere;font-size:12px"><thead><tr><th style="width:18%">Konu</th><th style="width:10%">Kapsam</th><th style="width:31%">Bugünkü model</th><th style="width:41%">Kalan ayrıntılar</th></tr></thead><tbody>${STM_SCOPE.map(([name,status,done,remaining])=>`<tr style="border-bottom:1px solid #334155"><td style="padding:10px;vertical-align:top"><strong>${esc(name)}</strong></td><td style="padding:10px;vertical-align:top;color:${status==='Bekliyor'?'#fbbf24':'#7dd3fc'}">${status}</td><td style="padding:10px;vertical-align:top">${esc(done)}</td><td style="padding:10px;vertical-align:top">${esc(remaining)}</td></tr>`).join('')}</tbody></table></div><p>Kontrol: gerçek C firmware, elektriksel hatlar, register/IRQ ve otomatik regresyon. Fiziksel donanımın tamamı doğrulanmış değildir.</p><p><a href="./notices/STM32-AUDIT.md" target="_blank">Ayrıntılı denetim ve devam sırası ↗</a> · <a href="${esc(b.source)}" target="_blank">ST datasheet ↗</a>${b.boardSource?` · <a href="${esc(b.boardSource)}" target="_blank">Üretici şeması ↗</a>`:''}</p>`);document.getElementById('dialog').classList.add('stm-config-dialog');}
